// BlitzLLVM runtime library.
//
// This file is embedded into the compiler and compiled together with the generated LLVM IR, so that the result is a
// single executable. Everything that Blitz programs can call lives here, prefixed with bb_.
//
// Strings are NUL-terminated UTF-8, where NULL is the empty string. Strings are immutable and currently never freed.

#include <ctype.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#if defined(_WIN32)
__declspec(dllimport) void __stdcall Sleep(unsigned long);
__declspec(dllimport) int __stdcall SetConsoleOutputCP(unsigned int);
#else
#include <unistd.h>
#endif

static const char* bb_s(const char* s)
{
	return s ? s : "";
}

static char* bb_alloc(size_t length)
{
	char* mem = (char*)malloc(length + 1);
	if (!mem) {
		fputs("Out of memory.\n", stderr);
		exit(1);
	}
	mem[length] = 0;
	return mem;
}

static char* bb_copy(const char* data, size_t length)
{
	char* mem = bb_alloc(length);
	memcpy(mem, data, length);
	return mem;
}

////////////////////////////////////////////////////////////////////////////////
// Who owns a string
//
// Strings that a function returns are temporaries: they are collected in the pool, and the program frees them when the
// statement that made them is done. Variables, fields and array elements own a copy of what they were given, which is
// freed when they are given something else, or when what they are in goes away.
////////////////////////////////////////////////////////////////////////////////
static char** bb_pool      = NULL;
static size_t bb_pool_size = 0;
static size_t bb_pool_cap  = 0;

static char* bb_own(const char* s)
{
	if (!s || !*s) {
		return NULL; // The empty string needs no memory.
	}
	size_t length = strlen(s);
	char*  mem    = (char*)malloc(length + 1);
	if (!mem) {
		fputs("Out of memory.\n", stderr);
		exit(1);
	}
	memcpy(mem, s, length + 1);
	return mem;
}

static void bb_pool_push(char* s)
{
	if (bb_pool_size == bb_pool_cap) {
		bb_pool_cap = bb_pool_cap ? bb_pool_cap * 2 : 256;
		bb_pool     = (char**)realloc(bb_pool, bb_pool_cap * sizeof(char*));
		if (!bb_pool) {
			fputs("Out of memory.\n", stderr);
			exit(1);
		}
	}
	bb_pool[bb_pool_size++] = s;
}

// Makes a string that a function returned a temporary.
const char* bb_str_temp(const char* s)
{
	if (s) {
		bb_pool_push((char*)s);
	}
	return s;
}

int32_t bb_str_mark(void)
{
	return (int32_t)bb_pool_size;
}

// Frees the temporaries that were made since the mark.
void bb_str_release(int32_t mark)
{
	while (bb_pool_size > (size_t)mark) {
		free(bb_pool[--bb_pool_size]);
	}
}

// For what a variable, field or element gets: its own copy, and the old one is freed.
const char* bb_str_assign(const char* old, const char* value)
{
	char* copy = bb_own(value);
	free((char*)old);
	return copy;
}

const char* bb_str_dup(const char* value)
{
	return bb_own(value);
}

void bb_str_free(const char* s)
{
	free((char*)s);
}

void bb_str_free_array(const char** elements, int32_t count)
{
	for (int32_t i = 0; i < count; i++) {
		free((char*)elements[i]);
		elements[i] = NULL;
	}
}

// What a function gives back: a copy that lives on as a temporary of whoever called, after those of the function are freed.
const char* bb_str_return(const char* value, int32_t mark)
{
	char* copy = bb_own(value);
	bb_str_release(mark);
	if (copy) {
		bb_pool_push(copy);
	}
	return copy;
}

////////////////////////////////////////////////////////////////////////////////
// Program
////////////////////////////////////////////////////////////////////////////////
extern void bb_set_arguments(int32_t argc, char** argv);

void bb_init(int32_t argc, char** argv)
{
	bb_set_arguments(argc, argv);
#if defined(_WIN32)
	SetConsoleOutputCP(65001);
#endif
}

void bb_end(void)
{
	fflush(stdout);
	exit(0);
}

void bb_runtime_error(const char* message)
{
	fflush(stdout);
	fprintf(stderr, "Runtime Error: %s\n", bb_s(message));
	exit(1);
}

void bb_check_div(int64_t divisor)
{
	if (divisor == 0) {
		bb_runtime_error("Integer divide by zero");
	}
}

////////////////////////////////////////////////////////////////////////////////
// Objects (Types)
//
// Every object starts with this header, which the compiler knows about (see register_types). Objects of a type are
// in a doubly linked list. Deleted objects are taken out of the list and flagged, but their memory is kept, so that
// variables that still point at them can be detected, and loops over the list can carry on.
////////////////////////////////////////////////////////////////////////////////
#define BB_OBJECT_DELETED 1

typedef struct bb_object {
	struct bb_object* next;
	struct bb_object* prev;
	int32_t           handle;
	int32_t           flags;
} bb_object;

typedef struct bb_list {
	bb_object*     first;
	bb_object*     last;
	const int32_t* strings; // How many fields (or arrays of them) are strings, then the offset and the count of each.
} bb_list;

// Handles are numbers that stand in for objects. Index 0 is never used.
static bb_object** bb_handles     = NULL;
static int32_t     bb_handle_count = 1;
static int32_t     bb_handle_cap   = 0;

static void bb_list_append(bb_list* list, bb_object* object)
{
	object->prev = list->last;
	object->next = NULL;
	if (list->last) {
		list->last->next = object;
	} else {
		list->first = object;
	}
	list->last = object;
}

static void bb_list_unlink(bb_list* list, bb_object* object)
{
	// The object keeps its own next and previous pointers, so that a loop standing on it can continue.
	if (object->prev) {
		object->prev->next = object->next;
	} else {
		list->first = object->next;
	}
	if (object->next) {
		object->next->prev = object->prev;
	} else {
		list->last = object->prev;
	}
}

void* bb_object_new(int64_t size, bb_list* list)
{
	bb_object* object = (bb_object*)calloc(1, (size_t)size);
	if (!object) {
		bb_runtime_error("Out of memory.");
	}
	bb_list_append(list, object);
	return object;
}

void bb_check_object(void* pointer)
{
	bb_object* object = (bb_object*)pointer;
	if (!object || (object->flags & BB_OBJECT_DELETED)) {
		bb_runtime_error("Object does not exist.");
	}
}

void bb_object_delete(bb_object* object, bb_list* list)
{
	if (!object || (object->flags & BB_OBJECT_DELETED)) {
		return;
	}
	bb_list_unlink(list, object);
	object->flags |= BB_OBJECT_DELETED;
	if (list->strings) {
		// The object stays readable after it is deleted, with empty strings.
		for (int32_t i = 0; i < list->strings[0]; i++) {
			char** slot  = (char**)((char*)object + list->strings[1 + 2 * i]);
			int32_t count = list->strings[2 + 2 * i];
			for (int32_t k = 0; k < (count ? count : 1); k++) {
				free(slot[k]);
				slot[k] = NULL;
			}
		}
	}
	if (object->handle > 0) {
		bb_handles[object->handle] = NULL;
	}
}

void bb_list_clear(bb_list* list)
{
	while (list->first) {
		bb_object_delete(list->first, list);
	}
}

bb_object* bb_list_first(bb_list* list)
{
	return list->first;
}

bb_object* bb_list_last(bb_list* list)
{
	return list->last;
}

bb_object* bb_object_next(bb_object* object)
{
	if (!object) {
		return NULL;
	}
	bb_object* next = object->next;
	while (next && (next->flags & BB_OBJECT_DELETED)) {
		next = next->next;
	}
	return next;
}

bb_object* bb_object_prev(bb_object* object)
{
	if (!object) {
		return NULL;
	}
	bb_object* prev = object->prev;
	while (prev && (prev->flags & BB_OBJECT_DELETED)) {
		prev = prev->prev;
	}
	return prev;
}

// Insert object Before/After other: moves the object within its list.
void bb_object_insert(bb_object* object, bb_object* other, int32_t after, bb_list* list)
{
	bb_check_object(object);
	bb_check_object(other);
	if (object == other) {
		return;
	}
	bb_list_unlink(list, object);
	if (after) {
		object->prev = other;
		object->next = other->next;
		if (other->next) {
			other->next->prev = object;
		} else {
			list->last = object;
		}
		other->next = object;
	} else {
		object->next = other;
		object->prev = other->prev;
		if (other->prev) {
			other->prev->next = object;
		} else {
			list->first = object;
		}
		other->prev = object;
	}
}

int32_t bb_handle(bb_object* object)
{
	if (!object || (object->flags & BB_OBJECT_DELETED)) {
		return 0;
	}
	if (object->handle == 0) {
		if (bb_handle_count >= bb_handle_cap) {
			bb_handle_cap = bb_handle_cap ? bb_handle_cap * 2 : 1024;
			bb_handles    = (bb_object**)realloc(bb_handles, (size_t)bb_handle_cap * sizeof(bb_object*));
			if (!bb_handles) {
				bb_runtime_error("Out of memory.");
			}
		}
		object->handle              = bb_handle_count;
		bb_handles[bb_handle_count] = object;
		bb_handle_count++;
	}
	return object->handle;
}

bb_object* bb_object_from_handle(int32_t handle)
{
	if ((handle <= 0) || (handle >= bb_handle_count)) {
		return NULL;
	}
	return bb_handles[handle];
}

void bb_check_index(int32_t index, int32_t count)
{
	if ((index < 0) || (index >= count)) {
		bb_runtime_error("Array index out of bounds.");
	}
}

// Dim: describes an array, see gen_dim_address in the compiler. The upper bounds are given, and each dimension has one
// element more than that. Dimensioning again discards what was in the array.
typedef struct bb_array {
	void*   data;
	int32_t size[4];
} bb_array;

void bb_dim(bb_array* array, int64_t element_size, int32_t dimensions, int32_t b0, int32_t b1, int32_t b2, int32_t b3)
{
	int32_t bounds[4] = { b0, b1, b2, b3 };
	int64_t total     = 1;
	for (int32_t i = 0; i < 4; i++) {
		if (i < dimensions) {
			if (bounds[i] < 0) {
				bb_runtime_error("Array sizes can't be negative.");
			}
			array->size[i] = bounds[i] + 1;
			total *= array->size[i];
		} else {
			array->size[i] = 0;
		}
	}
	free(array->data);
	array->data = calloc((size_t)total, (size_t)element_size);
	if (!array->data) {
		bb_runtime_error("Out of memory.");
	}
}

// Data, Read and Restore. The compiler collects the items of all Data statements into a table.
typedef struct bb_data_item {
	int32_t tag; // 0 = integer, 1 = real (the bits of a double), 2 = string (a pointer)
	int64_t value;
} bb_data_item;

static const bb_data_item* bb_data_take(const bb_data_item* table, int32_t count, int32_t* position)
{
	if (*position >= count) {
		bb_runtime_error("Out of data.");
	}
	return &table[(*position)++];
}

const char* bb_str_from_i64(int64_t v);
const char* bb_str_from_f64(double v);
int64_t     bb_str_to_i64(const char* s);
double      bb_str_to_f64(const char* s);

static double bb_data_double(const bb_data_item* item)
{
	double d;
	memcpy(&d, &item->value, sizeof(d));
	return d;
}

int32_t bb_data_int(const bb_data_item* table, int32_t count, int32_t* position)
{
	const bb_data_item* item = bb_data_take(table, count, position);
	switch (item->tag) {
	case 1:
		return (int32_t)bb_data_double(item);
	case 2:
		return (int32_t)bb_str_to_i64((const char*)(intptr_t)item->value);
	default:
		return (int32_t)item->value;
	}
}

float bb_data_float(const bb_data_item* table, int32_t count, int32_t* position)
{
	const bb_data_item* item = bb_data_take(table, count, position);
	switch (item->tag) {
	case 1:
		return (float)bb_data_double(item);
	case 2:
		return (float)bb_str_to_f64((const char*)(intptr_t)item->value);
	default:
		return (float)item->value;
	}
}

const char* bb_data_string(const bb_data_item* table, int32_t count, int32_t* position)
{
	const bb_data_item* item = bb_data_take(table, count, position);
	switch (item->tag) {
	case 1:
		return bb_str_from_f64(bb_data_double(item));
	case 2:
		return (const char*)(intptr_t)item->value;
	default:
		return bb_str_from_i64(item->value);
	}
}

////////////////////////////////////////////////////////////////////////////////
// Strings and conversion
////////////////////////////////////////////////////////////////////////////////
int32_t bb_len(const char* s)
{
	return (int32_t)strlen(bb_s(s));
}

int32_t bb_str_cmp(const char* a, const char* b)
{
	int r = strcmp(bb_s(a), bb_s(b));
	return (r < 0) ? -1 : ((r > 0) ? 1 : 0);
}

const char* bb_str_concat(const char* a, const char* b)
{
	size_t la = strlen(bb_s(a)), lb = strlen(bb_s(b));
	char*  r  = bb_alloc(la + lb);
	memcpy(r, bb_s(a), la);
	memcpy(r + la, bb_s(b), lb);
	return r;
}

const char* bb_str_from_i64(int64_t v)
{
	char buf[32];
	int  n = snprintf(buf, sizeof(buf), "%lld", (long long)v);
	return bb_copy(buf, (size_t)n);
}

const char* bb_str_from_u64(uint64_t v)
{
	char buf[32];
	int  n = snprintf(buf, sizeof(buf), "%llu", (unsigned long long)v);
	return bb_copy(buf, (size_t)n);
}

// Reals print with up to 6 significant digits, and always show a fractional part ("1.0", "0.5").
const char* bb_str_from_f64(double v)
{
	char buf[64];
	if (isnan(v)) {
		return bb_copy("NaN", 3);
	} else if (isinf(v)) {
		return v < 0 ? bb_copy("-Infinity", 9) : bb_copy("Infinity", 8);
	}
	int n = snprintf(buf, sizeof(buf), "%.6g", v);
	if (!strpbrk(buf, ".eE")) {
		n += snprintf(buf + n, sizeof(buf) - (size_t)n, ".0");
	}
	return bb_copy(buf, (size_t)n);
}

int64_t bb_str_to_i64(const char* s)
{
	s = bb_s(s);
	while (isspace((unsigned char)*s)) {
		s++;
	}
	// Blitz converts through floating point when the string looks like a real.
	char*   end;
	int64_t v = (int64_t)strtoll(s, &end, 10);
	if ((*end == '.') || (*end == 'e') || (*end == 'E')) {
		return (int64_t)strtod(s, NULL);
	}
	return v;
}

double bb_str_to_f64(const char* s)
{
	return strtod(bb_s(s), NULL);
}

const char* bb_left(const char* s, int32_t n)
{
	size_t len = strlen(bb_s(s));
	if (n < 0) {
		n = 0;
	}
	return bb_copy(bb_s(s), ((size_t)n < len) ? (size_t)n : len);
}

const char* bb_right(const char* s, int32_t n)
{
	size_t len = strlen(bb_s(s));
	if (n < 0) {
		n = 0;
	}
	size_t take = ((size_t)n < len) ? (size_t)n : len;
	return bb_copy(bb_s(s) + (len - take), take);
}

// Mid$(s, start[, count]), start is 1-based. A count below zero means "until the end".
const char* bb_mid(const char* s, int32_t start, int32_t count)
{
	size_t len = strlen(bb_s(s));
	if (start < 1) {
		start = 1;
	}
	if ((size_t)(start - 1) >= len) {
		return bb_copy("", 0);
	}
	size_t avail = len - (size_t)(start - 1);
	size_t take  = (count < 0 || (size_t)count > avail) ? avail : (size_t)count;
	return bb_copy(bb_s(s) + (start - 1), take);
}

const char* bb_upper(const char* s)
{
	size_t len = strlen(bb_s(s));
	char*  r   = bb_copy(bb_s(s), len);
	for (size_t i = 0; i < len; i++) {
		r[i] = (char)toupper((unsigned char)r[i]);
	}
	return r;
}

const char* bb_lower(const char* s)
{
	size_t len = strlen(bb_s(s));
	char*  r   = bb_copy(bb_s(s), len);
	for (size_t i = 0; i < len; i++) {
		r[i] = (char)tolower((unsigned char)r[i]);
	}
	return r;
}

const char* bb_trim(const char* s)
{
	const char* b = bb_s(s);
	while (isspace((unsigned char)*b)) {
		b++;
	}
	size_t len = strlen(b);
	while (len && isspace((unsigned char)b[len - 1])) {
		len--;
	}
	return bb_copy(b, len);
}

const char* bb_chr(int32_t c)
{
	char buf[1] = { (char)c };
	return bb_copy(buf, 1);
}

int32_t bb_asc(const char* s)
{
	return (int32_t)(unsigned char)bb_s(s)[0];
}

// Instr(s, find[, start]), 1-based, 0 if not found.
int32_t bb_instr(const char* s, const char* find, int32_t start)
{
	size_t len = strlen(bb_s(s));
	if (start < 1) {
		start = 1;
	}
	if ((size_t)(start - 1) > len) {
		return 0;
	}
	const char* p = strstr(bb_s(s) + (start - 1), bb_s(find));
	return p ? (int32_t)(p - bb_s(s)) + 1 : 0;
}

const char* bb_replace(const char* s, const char* from, const char* to)
{
	s    = bb_s(s);
	from = bb_s(from);
	to   = bb_s(to);
	size_t lf = strlen(from), lt = strlen(to);
	if (lf == 0) {
		return bb_copy(s, strlen(s));
	}
	size_t count = 0;
	for (const char* p = s; (p = strstr(p, from)); p += lf) {
		count++;
	}
	char* r   = bb_alloc(strlen(s) + count * lt - count * lf);
	char* out = r;
	const char* p;
	while ((p = strstr(s, from))) {
		memcpy(out, s, (size_t)(p - s));
		out += p - s;
		memcpy(out, to, lt);
		out += lt;
		s = p + lf;
	}
	strcpy(out, s);
	return r;
}

const char* bb_string_repeat(const char* s, int32_t n)
{
	size_t len = strlen(bb_s(s));
	if (n < 0) {
		n = 0;
	}
	char* r = bb_alloc(len * (size_t)n);
	for (int32_t i = 0; i < n; i++) {
		memcpy(r + len * (size_t)i, bb_s(s), len);
	}
	return r;
}

const char* bb_hex(int32_t v)
{
	char buf[16];
	int  n = snprintf(buf, sizeof(buf), "%08X", (unsigned)v);
	return bb_copy(buf, (size_t)n);
}

const char* bb_bin(int32_t v)
{
	char buf[33];
	for (int i = 0; i < 32; i++) {
		buf[i] = ((unsigned)v & (1u << (31 - i))) ? '1' : '0';
	}
	return bb_copy(buf, 32);
}

////////////////////////////////////////////////////////////////////////////////
// Console
////////////////////////////////////////////////////////////////////////////////
void bb_print(const char* s)
{
	fputs(bb_s(s), stdout);
	fputc('\n', stdout);
}

void bb_write(const char* s)
{
	fputs(bb_s(s), stdout);
}

const char* bb_input(const char* prompt)
{
	fputs(bb_s(prompt), stdout);
	fflush(stdout);
	char   buf[4096];
	if (!fgets(buf, sizeof(buf), stdin)) {
		return bb_copy("", 0);
	}
	size_t len = strlen(buf);
	while (len && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) {
		len--;
	}
	return bb_copy(buf, len);
}

////////////////////////////////////////////////////////////////////////////////
// Math
////////////////////////////////////////////////////////////////////////////////
static const double bb_deg = 3.14159265358979323846 / 180.0;

// Blitz trigonometry works in degrees.
float bb_sin(float v)   { return (float)sin((double)v * bb_deg); }
float bb_cos(float v)   { return (float)cos((double)v * bb_deg); }
float bb_tan(float v)   { return (float)tan((double)v * bb_deg); }
float bb_asin(float v)  { return (float)(asin((double)v) / bb_deg); }
float bb_acos(float v)  { return (float)(acos((double)v) / bb_deg); }
float bb_atan(float v)  { return (float)(atan((double)v) / bb_deg); }
float bb_atan2(float y, float x) { return (float)(atan2((double)y, (double)x) / bb_deg); }
float bb_sqr(float v)   { return sqrtf(v); }
float bb_floor(float v) { return floorf(v); }
float bb_ceil(float v)  { return ceilf(v); }
float bb_exp(float v)   { return expf(v); }
float bb_log(float v)   { return logf(v); }
float bb_log10(float v) { return log10f(v); }

////////////////////////////////////////////////////////////////////////////////
// Random
////////////////////////////////////////////////////////////////////////////////
static uint64_t bb_rng = 0x9E3779B97F4A7C15ull;

static uint64_t bb_rng_next(void)
{
	// xorshift64*
	bb_rng ^= bb_rng >> 12;
	bb_rng ^= bb_rng << 25;
	bb_rng ^= bb_rng >> 27;
	return bb_rng * 0x2545F4914F6CDD1Dull;
}

void bb_seed_rnd(int32_t seed)
{
	bb_rng = 0x9E3779B97F4A7C15ull ^ ((uint64_t)(uint32_t)seed * 0xBF58476D1CE4E5B9ull);
	if (bb_rng == 0) {
		bb_rng = 1;
	}
}

float bb_rnd(float lo, float hi)
{
	double unit = (double)(bb_rng_next() >> 11) / 9007199254740992.0;
	return (float)((double)lo + unit * ((double)hi - (double)lo));
}

int32_t bb_rand(int32_t lo, int32_t hi)
{
	if (hi < lo) {
		int32_t t = lo;
		lo        = hi;
		hi        = t;
	}
	uint64_t span = (uint64_t)((int64_t)hi - (int64_t)lo) + 1;
	return (int32_t)((int64_t)lo + (int64_t)(bb_rng_next() % span));
}

////////////////////////////////////////////////////////////////////////////////
// Time
////////////////////////////////////////////////////////////////////////////////
int32_t bb_millisecs(void)
{
	struct timespec ts;
	timespec_get(&ts, TIME_UTC);
	return (int32_t)(((int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000) & 0x7FFFFFFF);
}

void bb_graphics_idle(void);

void bb_delay(int32_t ms)
{
	fflush(stdout);
	// Wait in small steps, so that the window stays responsive and shows what was drawn.
	do {
		bb_graphics_idle();
		int32_t step = (ms > 10) ? 10 : ms;
		if (step > 0) {
#if defined(_WIN32)
			Sleep((unsigned long)step);
#else
			usleep((useconds_t)step * 1000);
#endif
		}
		ms -= step;
	} while (ms > 0);
}

